        if outcome.exit_code in (0, None):
            return TestRunStatus.FAILED_TO_PARSE
        return TestRunStatus.FAILED
    if outcome.exit_code in (0, None):
        return TestRunStatus.PASSED
    return TestRunStatus.FAILED

